INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (2834, 40, 7, "青空の下で謁見", 10118, 8, 1, "ペコリーヌとの出会い", 0, 20063115, "フリーマーケット会場", 2, 5118061, 91002, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (2835, 40, 7, "未来の騎空団\nマスコット？", 10118, 8, 1, "マホとの出会い", 0, 20063115, "フリーマーケット会場", 2, 5118062, 91002, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (2837, 40, 7, "お嬢さまからの\n緊急依頼", 10118, 8, 1, "アキノとの出会い", 0, 20063115, "ランドソル市街地", 2, 5118063, 91002, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (4108402, 40, 18, "黄金色の悩みごと", 10118, 8, 1, "ジュンとの出会い", 0, 20063115, "フリーマーケット会場", 2, 5118064, 91002, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (4107402, 40, 18, "白熱！　格闘大会！", 10118, 8, 1, "カオリとの出会い", 0, 20063115, "フリーマーケット会場", 2, 5118065, 91002, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (9000227, 40, 16, "祭り太鼓はオーエドの華", 10118, 8, 1, "ニノンとの出会い", 1, 20063115, "オーエド町", 2, 5118066, 91002, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (2101181, 40, 19, "人気者は遅れて\nやってくる", 10118, 8, 1, "スズナとの出会い", 0, 20063115, "フリーマーケット会場", 3, 5118067, 91002, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (4109402, 40, 18, "巫女・ミーツ・魔法少女", 10118, 8, 1, "ナナカとの出会い", 0, 20063115, "ランドソル市街地", 3, 5118068, 91002, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (4305402, 40, 18, "ネズ耳は二度なくなる", 10118, 8, 1, "キャル＆コッコロとの出会い", 0, 20063115, "フリーマーケット会場", 3, 5118069, 91002, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (4101402, 40, 18, "この出会いにカンパイ！", 10118, 8, 1, "ユカリとの出会い", 0, 20063115, "ランドソル市街地", 3, 5118070, 91002, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (4106402, 40, 18, "陰陽アンサンブル", 10118, 8, 1, "アオイとの出会い", 0, 20063115, "ランドソル市街地", 3, 5118071, 91002, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (2836, 40, 7, "運試し十番勝負！", 10118, 8, 1, "シノブとの出会い", 1, 20063115, "フリーマーケット会場", 3, 5118072, 91002, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (0, 0, 0, "彼女たちの新たな日常", 10118, 0, 0, "オープニング", 0, 20063115, 0, 1, 5118600, 0, 0);
